"""World: the LCG, pipe spawning, scrolling and culling."""

from units import SPAWN_X, SCROLL, PIPE_W


def lcg(s):
    """Advance the LCG once; return the new state."""
    return (1103515245 * s + 12345) % 2147483648


def spawn(t, s):
    """If tick t is a spawn tick, return (new_state, pipe_or_None).

    The LCG advances exactly once per spawn, before the gap is computed.
    """
    if t % 45 != 0:
        return s, None
    s = lcg(s)
    gap_top = 40 + (s >> 8) % 80
    return s, {"x": SPAWN_X, "gap_top": gap_top, "passed": False}


def scroll(pipes):
    """Move every pipe left by SCROLL. Mutates in place."""
    for p in pipes:
        p["x"] -= SCROLL


def cull(pipes):
    """Drop every pipe with x + PIPE_W <= 0. Returns the surviving list."""
    return [p for p in pipes if p["x"] + PIPE_W > 0]

"""Game loop: runs the per-tick order from spec/02 and returns final state."""

from units import BIRD_X, PIPE_W, GLIDE_VY
from physics import step_bird
from world import spawn, scroll, cull
from collide import pipe_hit


def _score(pipes, y, vy, score):
    """Step 5: score pipes whose right edge is at or behind the bird's left."""
    for p in pipes:
        if not p["passed"] and p["x"] + PIPE_W <= BIRD_X:
            p["passed"] = True
            score += 1
            if abs(vy) <= GLIDE_VY:
                score += 1
    return score


def run(seed, ticks, flaps, powerups=False):
    """Simulate `ticks` ticks. Returns the final state dict."""
    y, vy, alive = 560, 0, True
    score, s, pipes = 0, seed, []
    shields = 1 if powerups else 0
    passed_count = 0
    ticks_run = 0
    for t in range(ticks):
        if not alive:
            break
        ticks_run += 1
        flap = flaps[t % len(flaps)] == "1"
        s, pipe = spawn(t, s)
        if pipe is not None:
            pipes.append(pipe)
        y, vy, alive = step_bird(y, vy, flap)
        scroll(pipes)
        if alive:
            for p in pipes:
                if pipe_hit(y, p):
                    if powerups and shields > 0:
                        shields -= 1
                        p["passed"] = True
                    else:
                        alive = False
                    break
        if alive:
            score = _score(pipes, y, vy, score)
            passed_count += sum(1 for p in pipes if p["passed"])
            if powerups and passed_count % 5 == 0:
                shields = min(shields + 1, 3)
        pipes = cull(pipes)
    state = {"y": y, "vy": vy, "score": score, "alive": alive,
             "ticks_run": ticks_run}
    if powerups:
        state["shields"] = shields
    return state

"""Command line for flapsim: hand-parsed argv, exact output format."""

import sys
from engine import run


def _parse(argv):
    """Parse --seed/--ticks/--flaps/--powerups by hand. Returns dict or None."""
    opts = {"seed": 0, "ticks": 0, "flaps": "0", "powerups": False}
    i = 1
    while i < len(argv):
        a = argv[i]
        if a == "--selfcheck":
            return {"selfcheck": True}
        if a in ("--seed", "--ticks") and i + 1 < len(argv):
            opts[a[2:]] = int(argv[i + 1])
            i += 2
        elif a == "--flaps" and i + 1 < len(argv):
            opts["flaps"] = argv[i + 1] or "0"
            i += 2
        elif a == "--powerups":
            opts["powerups"] = True
            i += 1
        else:
            return None
    return opts


def _digest(st, n, powerups):
    line = ("DIGEST seed=%d ticks=%d score=%02d alive=%d y=%04d vy=%+05d "
            "ticks_run=%d" % (st["seed"], n, st["score"], int(st["alive"]),
                              st["y"], st["vy"], st["ticks_run"]))
    if powerups:
        line += " shields=%d" % st["shields"]
    return line


def _normal(opts):
    st = run(opts["seed"], opts["ticks"], opts["flaps"], opts["powerups"])
    st["seed"] = opts["seed"]
    n = opts["ticks"]
    every = max(1, n // 20)
    for t in range(n):
        if not st["alive"]:
            break
        run_t = run(opts["seed"], t + 1, opts["flaps"], opts["powerups"])
        if (t + 1) % every == 0:
            print("TRACE t=%04d y=%04d vy=%+05d score=%02d alive=%d"
                  % (t, run_t["y"], run_t["vy"], run_t["score"],
                     int(run_t["alive"])))
    print(_digest(st, n, opts["powerups"]))


def _selfcheck():
    cases = [(7, 200, "0010", 8, 1), (7, 120, "01", 0, 0),
             (3, 200, "0001", 8, 1), (11, 60, "1", 0, 0),
             (2, 90, "0", 0, 0), (5, 200, "0010", 8, 1)]
    for i, (seed, ticks, flaps, escore, ealive) in enumerate(cases, 1):
        st = run(seed, ticks, flaps)
        ok = st["score"] == escore and int(st["alive"]) == ealive
        print("EX%d seed=%d ticks=%d flaps=%s expect score=%02d alive=%d "
              "got score=%02d alive=%d %s"
              % (i, seed, ticks, flaps, escore, ealive, st["score"],
                 int(st["alive"]), "OK" if ok else "FAIL"))


def main(argv):
    opts = _parse(argv)
    if opts is None:
        print("usage: flapsim.py --seed S --ticks N --flaps BITS [--powerups]")
        return 1
    if opts.get("selfcheck"):
        _selfcheck()
    else:
        _normal(opts)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

